properties.query:
let alertWindow = 10m;
let baselineWindow = 7d;
let scanRateGate = 10.0;
let dynamicPortsGate = toscalar(
    UAVOpAudit_CL
    | where TimeGenerated > ago(baselineWindow)
    | where EventType == 'port_scan'
    | summarize percentile(PortsScanned, 95)
);
let portsScannedGate = max_of(coalesce(dynamicPortsGate, 15.0), 15.0);
UAVOpAudit_CL
| where TimeGenerated > ago(alertWindow)
| where EventType == 'port_scan'
| where PortsScanned >= portsScannedGate or ScanRatePerMin >= scanRateGate
| extend TriggerReason = strcat('능동정찰_포트스캔_', ScanSourceIp, '_Ports', tostring(PortsScanned), '_Rate', tostring(ScanRatePerMin))
| extend Severity = 'Medium'
| project TimeGenerated, ScanSourceIp, PortsScanned, ScanRatePerMin, PortsGate = portsScannedGate, Operator, TriggerReason, Severity
| order by TimeGenerated desc
